(()=>{const mode=new URLSearchParams(location.search).get('local-migrate');if(!mode){if(localStorage.getItem('hub:local-backend-enabled:v1')==='yes')location.replace('http://localhost:3010/ilya-communications-hub-app/');return;}const key='hub:folder-ops:v1',pending='hub:local-transfer:v1',destination='http://localhost:3010/ilya-communications-hub-app/';const meta=document.createElement('meta');meta.name='referrer';meta.content='origin';document.head.append(meta);try{if(mode==='ack'){const receipt=JSON.parse(decodeURIComponent(location.hash.slice(1))),saved=JSON.parse(localStorage.getItem(pending)||'null');if(new URL(document.referrer).origin!=='http://localhost:3010'||!saved||saved.nonce!==receipt.nonce)throw Error('The local transfer could not be verified. Original actions are retained.');const state=JSON.parse(localStorage.getItem(key)||'null');if(state){localStorage.setItem('hub:local-transfer-backup:v1',JSON.stringify(saved));state.jobs=state.jobs.filter(x=>!saved.ids.includes(x.id));localStorage.setItem(key,JSON.stringify(state));}localStorage.removeItem(pending);if(!state?.jobs?.length)localStorage.setItem('hub:local-backend-enabled:v1','yes');location.replace(state?.jobs?.length?location.pathname+'?local-migrate=1':destination);return}const state=JSON.parse(localStorage.getItem(key)||'null');if(!state?.jobs?.length){localStorage.setItem('hub:local-backend-enabled:v1','yes');location.replace(destination);return}const jobs=state.jobs.slice(0,50),ids=jobs.map(x=>x.id),messageIds=new Set(jobs.map(x=>x.body?.id).filter(Boolean)),nonce=crypto.randomUUID();const data={nonce,jobs,marks:Object.fromEntries(Object.entries(state.marks||{}).filter(([id])=>messageIds.has(id))),empty:(state.empty||[]).filter(x=>jobs.some(j=>j.body?.folder===x.folder)),deltas:(state.deltas||[]).filter(x=>ids.includes(x.jobId))};const fragment=encodeURIComponent(JSON.stringify(data));if(fragment.length>1500000)throw Error('This transfer is too large; original actions are retained.');localStorage.setItem(pending,JSON.stringify({nonce,ids,data}));location.replace(destination+'transfer.html#'+fragment)}catch(e){document.addEventListener('DOMContentLoaded',()=>{document.body.textContent=String(e.message||e)})}})();

